def dat_to_dataframe(dat_file): # from pyelmer.post import dat_to_dataframe
    """Read a .dat file generated by elmer (e.g. SaveData/SaveScalars
    solver) into a pandas dataframe.

    Args:
        dat_file (str): file path of elmer .dat file

    Returns:
        pandas.core.frame.DataFrame: content of dat file with header
    """
    with open(f"{dat_file}.names") as f:
        lines = f.readlines()
    names = []
    names_start = False
    for line in lines:
        if names_start == True:
            names.append(":".join(line.split(":")[1:]).strip())
        if (
            "Data on different columns" in line
            or "Variables in columns of matrix" in line
        ):
            names_start = True
    return pd.read_table(dat_file, names=names, sep='\s+')



def monotonically_ordered(array):
    """This function takes an array as input and returns a new array where the rows are sorted based on the first element of each row

    Args:
        array (float): 

    Returns:
        
    """
    #return sorted(array, key=lambda x: x[0])
    return np.array(sorted(array, key=lambda x: x[0]))


#--------------------------------------bottom part of the crystal  ------------------------------------#



def get_crystal_melt_interface(file_location):
    """
    returns the crystal melt interphase monotonically_ordered (from larger y-axis to smaller)
    Args:
        file_location (str): file path of 2-D boundary .dat file


    Returns:
        2D array of (x,y) of the interface line between crystal and melt
    """
    df = dat_to_dataframe(file_location)
    df_crystal_finalstep = df.loc[df["Call count"] == df["Call count"][df.index[-1]]] # last iteration
    coords_crystal = np.array(
    [
        df_crystal_finalstep["coordinate 1"].to_numpy(),
        df_crystal_finalstep["coordinate 2"].to_numpy(),
        df_crystal_finalstep["temperature"].to_numpy()
    ])

    newarray =np.column_stack((coords_crystal[0,:], coords_crystal[1,:]))

    return monotonically_ordered(newarray)
    #return newarray



