def T_bnd_for_3D(file_location,output_location,coord_int):
    """
    Args:
        file_location (str): file path of 2-D boundary .dat file
        output_location (str): file path of 3-D where coupling will be done .dat file
        coord_int (int): interpolation coordinate of the extracted array (x=0,y=1)

    Returns:
        2D array of the thermal boundaries and the coord_int
    """
    df = dat_to_dataframe(file_location)
    df_crystal_finalstep = df.loc[df["Call count"] == df["Call count"][df.index[-1]]] # last iteration
    coords_crystal = np.array(
    [
        df_crystal_finalstep["coordinate 1"].to_numpy(),
        df_crystal_finalstep["coordinate 2"].to_numpy(),
        df_crystal_finalstep["temperature"].to_numpy()
    ])

    newarray =np.column_stack((coords_crystal[coord_int,:], coords_crystal[2,:]))

    # Create a boolean mask for unique rows based on the first column
    mask = np.unique(newarray[:, 0], return_index=True)[1]

    # Use the mask to select only the unique rows
    filtered_data = newarray[mask]

    np.savetxt(output_location +os.path.basename(file_location), monotonically_ordered(filtered_data))

    return print("The file", os.path.basename(file_location), "was createad at :",output_location )


