def make_T_files(dir_2D,output_dir):

    crystal_T_boundary_side = dir_2D + '/crystal_T_boundary_side.dat'
    crystal_T_boundary_top = dir_2D + '/crystal_T_boundary_top.dat'
    crystal_T_boundary_bottom = dir_2D + '/phase-if.dat'

    T_bnd_for_3D(crystal_T_boundary_side,output_dir,1)
    T_bnd_for_3D(crystal_T_boundary_top,output_dir,0)
    #T_bnd_for_3D(crystal_T_boundary_bottom,output_dir,0)
    T_bnd_for_3D(crystal_T_boundary_bottom,output_dir,1)
    return print("------------------T files created in 3D folder -----------------")






